import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';

// Static checks of the app icons and the store listing drafts. Files are read
// as bytes or text; nothing is rendered. The icons and store graphics are
// generated by tool/brand/generate_icons.py from tool/brand/tether_mark.svg.

const String iosIconSet = 'ios/Runner/Assets.xcassets/AppIcon.appiconset';
const String androidRes = 'android/app/src/main/res';
const String playListing = 'docs/store/metadata/android/en-US';
const String iosListing = 'ios/fastlane/metadata/en-US';

/// Legacy launcher icon size (48dp) in pixels for each density folder.
const Map<String, int> legacyDensities = {
  'mdpi': 48,
  'hdpi': 72,
  'xhdpi': 96,
  'xxhdpi': 144,
  'xxxhdpi': 192,
};

/// SHA-1 of every icon file in the Flutter app template, as this repository
