/// Store wording a health app listing must not use without clinical and legal
/// sign-off. Matched as whole words, case-insensitively.
final List<RegExp> claimTerms = [
  for (final term in [
    'treat',
    'treats',
    'treatment',
    'cure',
    'cures',
    'diagnose',
    'diagnoses',
    'diagnosis',
    'clinically',
    'proven',
    'guaranteed',
    'FDA',
    'prescription',
    'doctor-approved',
  ])
    RegExp('\\b${RegExp.escape(term)}\\b', caseSensitive: false),
];

/// Width, height and PNG colour type from the IHDR chunk.
({int width, int height, int colorType}) pngHeader(Uint8List bytes) {
  const signature = [137, 80, 78, 71, 13, 10, 26, 10];
  expect(bytes.length, greaterThan(26));
  expect(bytes.sublist(0, 8), signature, reason: 'not a PNG');
  expect(ascii.decode(bytes.sublist(12, 16)), 'IHDR');
  final data = ByteData.sublistView(bytes);
  return (
    width: data.getUint32(16),
    height: data.getUint32(20),
    colorType: bytes[25],
  );
}

/// SHA-1 (FIPS 180-4) as lowercase hex. Small and local so the test needs no
/// package.
String sha1Hex(Uint8List message) {
  final ml = message.length * 8;
  final padded = BytesBuilder()
    ..add(message)
    ..addByte(0x80);
  while ((padded.length % 64) != 56) {
    padded.addByte(0);
  }
  final lengthBytes = ByteData(8)..setUint64(0, ml);
  padded.add(lengthBytes.buffer.asUint8List());
  final bytes = ByteData.sublistView(padded.toBytes());
  var h0 = 0x67452301, h1 = 0xEFCDAB89, h2 = 0x98BADCFE;
  var h3 = 0x10325476, h4 = 0xC3D2E1F0;
  int rotl(int x, int n) => ((x << n) | (x >> (32 - n))) & 0xFFFFFFFF;
  final w = List<int>.filled(80, 0);
  for (var chunk = 0; chunk < bytes.lengthInBytes; chunk += 64) {
    for (var i = 0; i < 16; i++) {
      w[i] = bytes.getUint32(chunk + i * 4);
    }
    for (var i = 16; i < 80; i++) {
      w[i] = rotl(w[i - 3] ^ w[i - 8] ^ w[i - 14] ^ w[i - 16], 1);
    }
    var a = h0, b = h1, c = h2, d = h3, e = h4;
    for (var i = 0; i < 80; i++) {
      int f, k;
      if (i < 20) {
        f = (b & c) | ((~b & 0xFFFFFFFF) & d);
        k = 0x5A827999;
      } else if (i < 40) {
        f = b ^ c ^ d;
        k = 0x6ED9EBA1;
      } else if (i < 60) {
        f = (b & c) | (b & d) | (c & d);
        k = 0x8F1BBCDC;
      } else {
        f = b ^ c ^ d;
        k = 0xCA62C1D6;
      }
      final temp = (rotl(a, 5) + f + e + k + w[i]) & 0xFFFFFFFF;
      e = d;
      d = c;
      c = rotl(b, 30);
      b = a;
      a = temp;
    }
    h0 = (h0 + a) & 0xFFFFFFFF;
    h1 = (h1 + b) & 0xFFFFFFFF;
    h2 = (h2 + c) & 0xFFFFFFFF;
    h3 = (h3 + d) & 0xFFFFFFFF;
    h4 = (h4 + e) & 0xFFFFFFFF;
  }
  return [h0, h1, h2, h3, h4]
      .map((h) => h.toRadixString(16).padLeft(8, '0'))
      .join();
}

/// A listing field: the file's text without the final newline.
String field(String dir, String name) {
  final file = File('$dir/$name');
  expect(file.existsSync(), isTrue, reason: '${file.path} is missing');
  final text = file.readAsStringSync();
  return text.endsWith('\n') ? text.substring(0, text.length - 1) : text;
}

/// Length as the stores count it: Unicode characters, not UTF-16 units.
int chars(String s) => s.runes.length;

void expectWithin(String dir, String name, int max) {
  final text = field(dir, name);
  expect(text.trim(), isNotEmpty, reason: '$dir/$name is empty');
  expect(text, text.trim(), reason: '$dir/$name has stray whitespace');
  expect(chars(text), lessThanOrEqualTo(max),
      reason: '$dir/$name is ${chars(text)} characters (limit $max)');
}

void expectNoClaims(String dir, String name) {
  final text = field(dir, name);
  for (final term in claimTerms) {
    expect(term.hasMatch(text), isFalse,
        reason: '$dir/$name uses "${term.pattern}"');
  }
}

/// Every icon file the app ships (iOS asset catalog and Android legacy).
List<File> shippedIcons() => [
      ...Directory(iosIconSet)
          .listSync()
          .whereType<File>()
          .where((f) => f.path.endsWith('.png')),
      for (final density in legacyDensities.keys)
        File('$androidRes/mipmap-$density/ic_launcher.png'),
    ];

void main() {
  group('sha1Hex', () {
    test('matches the FIPS 180 examples', () {
      expect(sha1Hex(Uint8List.fromList(utf8.encode('abc'))),
          'a9993e364706816aba3e25717850c26c9cd0d89d');
      expect(sha1Hex(Uint8List(0)), 'da39a3ee5e6b4b0d3255bfef95601890afd80709');
      expect(
          sha1Hex(Uint8List.fromList(utf8.encode(
              'abcdbcdecdefdefgefghfghighijhijkijkljklmklmnlmnomnopnopq'))),
          '84983e441c3bd26ebaae4aa1f95129e5e54670f1');
    });
  });

  group('iOS app icon', () {
    final contents =
        jsonDecode(File('$iosIconSet/Contents.json').readAsStringSync()) as Map;
    final images = (contents['images'] as List).cast<Map>();

    test('Contents.json lists the iPhone, iPad and marketing icons', () {
      final idioms = images.map((i) => i['idiom']).toSet();
      expect(idioms, containsAll(['iphone', 'ipad', 'ios-marketing']));
      expect(
          images.where(
              (i) => i['idiom'] == 'ios-marketing' && i['size'] == '1024x1024'),
          hasLength(1));
    });

    test('every listed file exists at size x scale pixels', () {
      for (final image in images) {
        final name = image['filename'] as String?;
        expect(name, isNotNull, reason: 'entry without a file: $image');
        final file = File('$iosIconSet/$name');
        expect(file.existsSync(), isTrue, reason: '$name is missing');
        final size = double.parse((image['size'] as String).split('x').first);
        final scale = int.parse((image['scale'] as String).replaceAll('x', ''));
        final px = (size * scale).round();
        final header = pngHeader(file.readAsBytesSync());
        expect([header.width, header.height], [px, px],
            reason: '$name should be ${px}x$px');
      }
    });

    test('icons are opaque (no alpha channel)', () {
      for (final image in images) {
        final name = image['filename'] as String;
        final header = pngHeader(File('$iosIconSet/$name').readAsBytesSync());
        // PNG colour type 2 is RGB without alpha.
        expect(header.colorType, 2, reason: '$name must have no alpha');
      }
    });

    test('no file in the icon set is unreferenced', () {
      final listed = images.map((i) => i['filename']).toSet();
      final onDisk = Directory(iosIconSet)
          .listSync()
          .whereType<File>()
          .map((f) => f.uri.pathSegments.last)
          .where((n) => n.endsWith('.png'));
      for (final name in onDisk) {
        expect(listed, contains(name), reason: '$name is not in Contents.json');
      }
    });
  });

  group('Android launcher icon', () {
    test('legacy icons exist at every density', () {
      legacyDensities.forEach((density, px) {
        final file = File('$androidRes/mipmap-$density/ic_launcher.png');
        expect(file.existsSync(), isTrue, reason: '${file.path} is missing');
        final header = pngHeader(file.readAsBytesSync());
        expect([header.width, header.height], [px, px],
            reason: '${file.path} should be ${px}x$px');
      });
    });

    test('adaptive icon has background, foreground and monochrome layers', () {
      const dir = '$androidRes/mipmap-anydpi-v26';
      final xml = File('$dir/ic_launcher.xml').readAsStringSync();
      expect(xml, contains('<adaptive-icon'));
      for (final layer in ['background', 'foreground', 'monochrome']) {
        expect(xml,
            contains('<$layer android:drawable="@mipmap/ic_launcher_$layer"'));
        final drawable = File('$dir/ic_launcher_$layer.xml');
        expect(drawable.existsSync(), isTrue,
            reason: '${drawable.path} is missing');
        final body = drawable.readAsStringSync();
        expect(body, contains('<vector'));
        expect(body, contains('android:viewportWidth="108"'));
      }
    });

    test('the manifest uses the launcher icon', () {
      final manifest =
          File('android/app/src/main/AndroidManifest.xml').readAsStringSync();
      expect(manifest, contains('android:icon="@mipmap/ic_launcher"'));
    });
  });

  group('icons and store graphics', () {
    test('no icon is a Flutter template icon', () {
      for (final file in shippedIcons()) {
        expect(flutterDefaultIconSha1,
            isNot(contains(sha1Hex(file.readAsBytesSync()))),
            reason: '${file.path} is the Flutter default icon');
      }
    });

    test('Play hi-res icon is 512 x 512 and the feature graphic 1024 x 500',
        () {
      final icon =
          pngHeader(File('docs/store/play-icon-512.png').readAsBytesSync());
      expect([icon.width, icon.height], [512, 512]);
      final feature =
          pngHeader(File('docs/store/feature-graphic.png').readAsBytesSync());
      expect([feature.width, feature.height], [1024, 500]);
      // Play requires a 24-bit PNG (no alpha) for the feature graphic.
      expect(feature.colorType, 2);
    });

    test('master artwork uses the design tokens', () {
      final svg = File('tool/brand/tether_mark.svg').readAsStringSync();
      final tokens = jsonDecode(
          File('specs-and-design/tether_ui/design/tokens.json')
              .readAsStringSync()) as Map;
      final colors = (tokens['colors'] ?? tokens['color']) as Map;
      expect(svg, contains('id="disc"'));
      expect(svg, contains('fill="${colors['teal']}"'));
      expect(svg, contains('id="leaf"'));
      expect(svg, contains('fill="${colors['lime']}"'));
    });
  });

  group('Google Play listing draft', () {
    test('fields are within Play limits', () {
      expectWithin(playListing, 'title.txt', 30);
      expectWithin(playListing, 'short_description.txt', 80);
      expectWithin(playListing, 'full_description.txt', 4000);
    });

    test('title is the app name', () {
      expect(field(playListing, 'title.txt'), 'Tether Health');
    });

    test('no medical claims', () {
      for (final name in [
        'title.txt',
        'short_description.txt',
        'full_description.txt',
      ]) {
        expectNoClaims(playListing, name);
      }
    });
  });

  group('App Store listing draft', () {
    test('fields are within App Store limits', () {
      expectWithin(iosListing, 'name.txt', 30);
      expectWithin(iosListing, 'subtitle.txt', 30);
      expectWithin(iosListing, 'description.txt', 4000);
      expectWithin(iosListing, 'keywords.txt', 100);
      expectWithin(iosListing, 'promotional_text.txt', 170);
    });

    test('name matches the app name', () {
      expect(field(iosListing, 'name.txt'), 'Tether Health');
    });

    test('keywords are comma-separated without empty entries', () {
      final keywords = field(iosListing, 'keywords.txt').split(',');
      expect(keywords.length, greaterThan(1));
      for (final k in keywords) {
        expect(k.trim(), isNotEmpty);
        expect(k, k.trim(), reason: 'spaces around "$k" waste characters');
      }
    });

    test('URLs are https on the company site', () {
      for (final name in [
        'privacy_url.txt',
        'support_url.txt',
        'marketing_url.txt',
      ]) {
        final url = Uri.parse(field(iosListing, name));
        expect(url.scheme, 'https', reason: name);
        expect(url.host, 'www.tetherhealthgroup.com', reason: name);
      }
    });

    test('no medical claims', () {
      for (final name in [
        'name.txt',
        'subtitle.txt',
        'description.txt',
        'keywords.txt',
        'promotional_text.txt',
      ]) {
        expectNoClaims(iosListing, name);
      }
    });
  });

  group('App Store compliance files', () {
    test('privacy manifest declares no tracking and is a Runner resource', () {
      final manifest =
          File('ios/Runner/PrivacyInfo.xcprivacy').readAsStringSync();
      expect(
          RegExp(r'<key>NSPrivacyTracking</key>\s*<false/>').hasMatch(manifest),
          isTrue);
      expect(
          RegExp(r'<key>NSPrivacyTrackingDomains</key>\s*<array/>')
              .hasMatch(manifest),
          isTrue);
      for (final type in [
        'EmailAddress',
        'Name',
        'UserID',
        'Health',
        'PhotosorVideos',
        'OtherUserContent',
      ]) {
        expect(manifest, contains('NSPrivacyCollectedDataType$type<'));
      }
      expect(
          RegExp(r'<key>NSPrivacyCollectedDataTypeTracking</key>\s*<true/>')
              .hasMatch(manifest),
          isFalse);
      final project =
          File('ios/Runner.xcodeproj/project.pbxproj').readAsStringSync();
      expect(project, contains('PrivacyInfo.xcprivacy in Resources */,'));
    });

    test('export compliance: no non-exempt encryption', () {
      final plist = File('ios/Runner/Info.plist').readAsStringSync();
      expect(
          RegExp(r'<key>ITSAppUsesNonExemptEncryption</key>\s*<false/>')
              .hasMatch(plist),
          isTrue);
    });
  });
}
